arguments.command:
python -c "
# More test cases for str.format
test_cases = [
    ('{}}}', False),  # field {}, then unmatched }
    ('{{abc', True),   # escaped {{, abc is literal text
    ('abc}}', True),   # abc is literal, escaped }}
    ('{{{', False),    # escaped {{, then unmatched {
    ('}}{', False),    # escaped }}, then unmatched {
    ('{a{b}', False),  # nested braces not supported
]

for fmt, expected_ok in test_cases:
    try:
        result = fmt.format()
        status = 'OK' if expected_ok else 'UNEXPECTED OK'
    except Exception as e:
        status = 'ERROR' if not expected_ok else f'UNEXPECTED ERROR: {type(e).__name__}'
    print(f'{status}: {repr(fmt):30} -> {e if expected_ok else \"\"}')
" 2>&1
